// Tema 10 · bloque 5 · Código Civil: patria potestad, desamparo, guarda y acogimiento (arts. 154-174) · IA estilo examen (10-ia-10601…)
const k = 'cc';
const Q = [
{k, a: 'art. 154', r: 'Patria potestad', e: 'Los hijos e hijas no emancipados están bajo la patria potestad de los progenitores. La patria potestad, como responsabilidad parental, se ejercerá siempre:',
 o: ['en interés de los hijos e hijas, de acuerdo con su personalidad, y con respeto a sus derechos, su integridad física y mental.', 'en interés de la familia, con respeto a la autoridad de los progenitores.', 'en interés de los progenitores, de acuerdo con la personalidad de los hijos.', 'en interés de los hijos, siempre que lo apruebe la autoridad judicial.'],
 t: 'La patria potestad, como responsabilidad parental, se ejercerá siempre en interés de los hijos e hijas, de acuerdo con su personalidad, y con respeto a sus derechos, su integridad física y mental', p: 'Siempre en interés de los hijos.'},
{k, a: 'art. 154', r: 'Patria potestad', e: 'La patria potestad comprende los siguientes deberes y facultades. Señale la INCORRECTA:',
 o: ['Decidir libremente el lugar de residencia habitual de la persona menor de edad.', 'Velar por ellos, tenerlos en su compañía, alimentarlos, educarlos y procurarles una formación integral.', 'Representarlos y administrar sus bienes.', 'Decidir el lugar de residencia habitual del menor con el consentimiento de ambos progenitores o, en su defecto, por autorización judicial.'],
 t: '3.º Decidir el lugar de residencia habitual de la persona menor de edad, que solo podrá ser modificado con el consentimiento de ambos progenitores o, en su defecto, por autorización judicial', p: 'La residencia solo puede modificarse con consentimiento de ambos o autorización judicial.'},
{k, a: 'art. 154', r: 'Patria potestad', e: 'Si los hijos o hijas tuvieren suficiente madurez deberán ser oídos siempre antes de adoptar decisiones que les afecten sea en procedimiento contencioso o de mutuo acuerdo. En todo caso, se garantizará que puedan ser oídas:',
 o: ['en condiciones idóneas, en términos que les sean accesibles, comprensibles y adaptados a su edad, madurez y circunstancias.', 'en presencia de ambos progenitores y del Ministerio Fiscal.', 'en la sede del Juzgado, con asistencia de letrado.', 'por escrito, con informe del Equipo Técnico.'],
 t: 'se garantizará que puedan ser oídas en condiciones idóneas, en términos que les sean accesibles, comprensibles y adaptados a su edad, madurez y circunstancias', p: 'En condiciones idóneas y adaptadas a su edad y madurez.'},
{k, a: 'art. 154', r: 'Patria potestad', e: 'Los progenitores podrán, en el ejercicio de su función de patria potestad:',
 o: ['recabar el auxilio de la autoridad.', 'delegar su ejercicio en los abuelos.', 'solicitar la intervención del Ministerio Fiscal.', 'recabar el auxilio de la Entidad Pública.'],
 t: 'Los progenitores podrán, en el ejercicio de su función, recabar el auxilio de la autoridad', p: 'Pueden recabar el auxilio de la autoridad.'},
{k, a: 'art. 155', r: 'Deberes de los hijos', e: 'Los hijos deben obedecer a sus padres mientras permanezcan bajo su potestad, y respetarles siempre, y además:',
 o: ['contribuir equitativamente, según sus posibilidades, al levantamiento de las cargas de la familia mientras convivan con ella.', 'contribuir económicamente al sostenimiento de la familia desde los dieciséis años.', 'prestar alimentos a sus ascendientes desde la mayoría de edad.', 'ayudar a los padres en las tareas domésticas mientras convivan con ellos.'],
 t: '2.° Contribuir equitativamente, según sus posibilidades, al levantamiento de las cargas de la familia mientras convivan con ella', p: 'Contribuyen equitativamente a las cargas familiares mientras convivan.'},
{k, a: 'art. 156', r: 'Ejercicio de la patria potestad', e: 'La patria potestad se ejercerá conjuntamente por ambos progenitores o por uno solo con el consentimiento expreso o tácito del otro. Serán válidos los actos que realice uno de ellos conforme al uso social y a las circunstancias o en situaciones de:',
 o: ['urgente necesidad.', 'riesgo para el menor.', 'ausencia del otro progenitor.', 'conflicto de intereses.'],
 t: 'Serán válidos los actos que realice uno de ellos conforme al uso social y a las circunstancias o en situaciones de urgente necesidad', p: 'En situaciones de urgente necesidad.'},
{k, a: 'art. 156', r: 'Ejercicio de la patria potestad', e: 'Si la asistencia psicológica hubiera de prestarse a los hijos e hijas mayores de dieciséis años, se precisará en todo caso:',
 o: ['el consentimiento expreso de estos.', 'el consentimiento de ambos progenitores.', 'la autorización judicial.', 'el informe del Ministerio Fiscal.'],
 t: 'Si la asistencia hubiera de prestarse a los hijos e hijas mayores de dieciséis años se precisará en todo caso el consentimiento expreso de estos', p: 'Se precisa el consentimiento expreso del propio hijo.'},
{k, a: 'art. 156', r: 'Ejercicio de la patria potestad', e: 'En caso de desacuerdo en el ejercicio de la patria potestad, cualquiera de los dos podrá acudir a la autoridad judicial, quien, después de oír a ambos y al hijo si tuviera suficiente madurez y, en todo caso, si fuera mayor de doce años:',
 o: ['atribuirá la facultad de decidir a uno de los dos progenitores.', 'atribuirá la facultad de decidir a ambos progenitores conjuntamente.', 'decidirá por sí misma sobre la cuestión planteada.', 'atribuirá la facultad de decidir al progenitor con quien conviva el hijo.'],
 t: 'después de oír a ambos y al hijo si tuviera suficiente madurez y, en todo caso, si fuera mayor de doce años, atribuirá la facultad de decidir a uno de los dos progenitores', p: 'Atribuye la facultad de decidir a uno de los progenitores.'},
{k, a: 'art. 156', r: 'Ejercicio de la patria potestad', e: 'Si los desacuerdos en el ejercicio de la patria potestad fueran reiterados o concurriera cualquier otra causa que entorpezca gravemente su ejercicio, la autoridad judicial podrá atribuirla total o parcialmente a uno de los progenitores o distribuir entre ellos sus funciones. Esta medida tendrá vigencia durante el plazo que se fije, que no podrá nunca exceder de:',
 o: ['dos años.', 'un año.', 'tres años.', 'seis meses.'],
 t: 'Esta medida tendrá vigencia durante el plazo que se fije, que no podrá nunca exceder de dos años', p: 'El plazo no puede exceder de dos años.'},
{k, a: 'art. 156', r: 'Ejercicio de la patria potestad', e: 'Respecto de terceros de buena fe, se presumirá que cada uno de los progenitores actúa en el ejercicio ordinario de la patria potestad:',
 o: ['con el consentimiento del otro.', 'con autorización judicial.', 'en interés del hijo.', 'con la asistencia del Ministerio Fiscal.'],
 t: 'respecto de terceros de buena fe, se presumirá que cada uno de los progenitores actúa en el ejercicio ordinario de la patria potestad con el consentimiento del otro', p: 'Se presume el consentimiento del otro.'},
{k, a: 'art. 156', r: 'Ejercicio de la patria potestad', e: 'En defecto o por ausencia o imposibilidad de uno de los progenitores, la patria potestad será ejercida:',
 o: ['exclusivamente por el otro.', 'por el otro, con autorización judicial.', 'por el otro, con asistencia del Ministerio Fiscal.', 'por la persona que designe el Juez.'],
 t: 'En defecto o por ausencia o imposibilidad de uno de los progenitores, la patria potestad será ejercida exclusivamente por el otro', p: 'La ejerce exclusivamente el otro progenitor.'},
{k, a: 'art. 156', r: 'Ejercicio de la patria potestad', e: 'Si los progenitores viven separados, la patria potestad se ejercerá por aquel con quien el hijo conviva. Sin embargo, la autoridad judicial, a solicitud fundada del otro progenitor, podrá, en interés del hijo:',
 o: ['atribuir al solicitante la patria potestad para que la ejerza conjuntamente con el otro progenitor o distribuir entre ambos las funciones inherentes a su ejercicio.', 'atribuir al solicitante la patria potestad con carácter exclusivo.', 'privar de la patria potestad al progenitor con quien conviva el hijo.', 'suspender el ejercicio de la patria potestad hasta que exista acuerdo.'],
 t: 'la autoridad judicial, a solicitud fundada del otro progenitor, podrá, en interés del hijo, atribuir al solicitante la patria potestad para que la ejerza conjuntamente con el otro progenitor o distribuir entre ambos las funciones inherentes a su ejercicio', p: 'La atribución es conjunta o con distribución de funciones.'},
{k, a: 'art. 157', r: 'Patria potestad del menor', e: 'El menor no emancipado ejercerá la patria potestad sobre sus hijos con la asistencia de sus padres y, a falta de ambos, de su tutor; en casos de desacuerdo o imposibilidad, con la del:',
 o: ['Juez.', 'Ministerio Fiscal.', 'tutor.', 'Encargado del Registro Civil.'],
 t: 'El menor no emancipado ejercerá la patria potestad sobre sus hijos con la asistencia de sus padres y, a falta de ambos, de su tutor; en casos de desacuerdo o imposibilidad, con la del Juez', p: 'En desacuerdo o imposibilidad, asiste el Juez.'},
{k, a: 'art. 158', r: 'Medidas judiciales de protección de los hijos', e: 'El Juez, de oficio o a instancia del propio hijo, de cualquier pariente o del Ministerio Fiscal, dictará las medidas convenientes para asegurar la prestación de alimentos y proveer a las futuras necesidades del hijo, en caso de:',
 o: ['incumplimiento de este deber, por sus padres.', 'separación de hecho de sus padres.', 'riesgo de desamparo del hijo.', 'conflicto de intereses entre sus padres.'],
 t: 'Las medidas convenientes para asegurar la prestación de alimentos y proveer a las futuras necesidades del hijo, en caso de incumplimiento de este deber, por sus padres', p: 'Se dictan en caso de incumplimiento por los padres.'},
{k, a: 'art. 158', r: 'Medidas judiciales de protección de los hijos', e: 'El Juez dictará la medida de prohibición a los progenitores, tutores, a otros parientes o a terceras personas de aproximarse al menor y acercarse a su domicilio o centro educativo y a otros lugares que frecuente, con respeto al principio de:',
 o: ['proporcionalidad.', 'subsidiariedad.', 'legalidad.', 'interés superior del menor.'],
 t: 'La medida de prohibición a los progenitores, tutores, a otros parientes o a terceras personas de aproximarse al menor y acercarse a su domicilio o centro educativo y a otros lugares que frecuente, con respecto al principio de proporcionalidad', p: 'Con respeto al principio de proporcionalidad.'},
{k, a: 'art. 158', r: 'Medidas judiciales de protección de los hijos', e: 'En caso de posible desamparo del menor, el Juzgado comunicará las medidas a la Entidad Pública. Todas estas medidas podrán adoptarse dentro de cualquier proceso judicial o penal o bien en:',
 o: ['un expediente de jurisdicción voluntaria, en que la autoridad judicial habrá de garantizar la audiencia de la persona menor de edad.', 'un procedimiento sumario especial ante el Juzgado de Familia.', 'un expediente administrativo ante la Entidad Pública.', 'un procedimiento de medidas cautelares previas.'],
 t: 'Todas estas medidas podrán adoptarse dentro de cualquier proceso judicial o penal o bien en un expediente de jurisdicción voluntaria, en que la autoridad judicial habrá de garantizar la audiencia de la persona menor de edad', p: 'Expediente de jurisdicción voluntaria con audiencia del menor.'},
{k, a: 'art. 158', r: 'Medidas judiciales de protección de los hijos', e: 'Entre las medidas que dicta el Juez para evitar la sustracción de los hijos menores por alguno de los progenitores o por terceras personas figura la prohibición de expedición del pasaporte al menor o:',
 o: ['retirada del mismo si ya se hubiere expedido.', 'suspensión de su validez durante un año.', 'comunicación a la Policía de las fronteras.', 'retirada del documento nacional de identidad.'],
 t: 'b) Prohibición de expedición del pasaporte al menor o retirada del mismo si ya se hubiere expedido', p: 'Retirada del pasaporte si ya se hubiere expedido.'},
{k, a: 'art. 158', r: 'Medidas judiciales de protección de los hijos', e: 'El Juez dictará la suspensión cautelar en el ejercicio de la patria potestad y/o en el ejercicio de la guarda y custodia, la suspensión cautelar del régimen de visitas y comunicaciones establecidos en resolución judicial o convenio judicialmente aprobado y, en general, las demás disposiciones que considere oportunas, a fin de:',
 o: ['apartar al menor de un peligro o de evitarle perjuicios en su entorno familiar o frente a terceras personas.', 'garantizar el cumplimiento de la sentencia de separación o divorcio.', 'evitar la sustracción del menor por alguno de los progenitores.', 'asegurar la prestación de alimentos al menor.'],
 t: 'a fin de apartar al menor de un peligro o de evitarle perjuicios en su entorno familiar o frente a terceras personas', p: 'Apartar al menor de un peligro o evitarle perjuicios.'},
{k, a: 'art. 159', r: 'Guarda de los hijos', e: 'Si los padres viven separados y no decidieren de común acuerdo, el Juez decidirá, siempre en beneficio de los hijos, al cuidado de qué progenitor quedarán los hijos menores de edad. El Juez oirá, antes de tomar esta medida, a los hijos que tuvieran suficiente juicio y, en todo caso, a los que fueran mayores de:',
 o: ['doce años.', 'catorce años.', 'dieciséis años.', 'diez años.'],
 t: 'El Juez oirá, antes de tomar esta medida, a los hijos que tuvieran suficiente juicio y, en todo caso, a los que fueran mayores de doce años', p: 'Mayores de doce años, en todo caso.'},
{k, a: 'art. 160', r: 'Relaciones personales', e: 'Los hijos menores tienen derecho a relacionarse con sus progenitores aunque éstos no ejerzan la patria potestad, salvo que se disponga otra cosa por resolución judicial o por:',
 o: ['la Entidad Pública en los casos establecidos en el Código.', 'el Ministerio Fiscal en los casos de riesgo.', 'el acuerdo de los progenitores.', 'la autoridad administrativa competente en materia de menores.'],
 t: 'salvo que se disponga otra cosa por resolución judicial o por la Entidad Pública en los casos establecidos en el artículo 161', p: 'Resolución judicial o decisión de la Entidad Pública.'},
{k, a: 'art. 160', r: 'Relaciones personales', e: 'En caso de privación de libertad de los progenitores, y siempre que el interés superior del menor recomiende visitas a aquellos, la visita a un centro penitenciario se deberá realizar:',
 o: ['fuera de horario escolar y en un entorno adecuado para el menor.', 'en horario escolar, con acompañamiento del tutor.', 'siempre en presencia del Ministerio Fiscal.', 'con autorización judicial en cada ocasión.'],
 t: 'Asimismo la visita a un centro penitenciario se deberá realizar fuera de horario escolar y en un entorno adecuado para el menor', p: 'Fuera de horario escolar y en entorno adecuado.'},
{k, a: 'art. 160', r: 'Relaciones personales', e: 'Los menores adoptados por otra persona, solo podrán relacionarse con su familia de origen:',
 o: ['en los términos previstos para el mantenimiento de la relación en la adopción.', 'con autorización del adoptante en todo caso.', 'previa aprobación del Ministerio Fiscal.', 'una vez alcanzada la mayoría de edad.'],
 t: 'Los menores adoptados por otra persona, solo podrán relacionarse con su familia de origen en los términos previstos en el artículo 178.4', p: 'Solo en los términos del mantenimiento de la relación en la adopción.'},
{k, a: 'art. 160', r: 'Relaciones personales', e: 'No podrán impedirse sin justa causa las relaciones personales del menor con sus hermanos, abuelos y otros parientes y allegados. En caso de oposición, el Juez resolverá a petición del menor, hermanos, abuelos, parientes o allegados:',
 o: ['atendidas las circunstancias.', 'previo informe del Ministerio Fiscal.', 'previa audiencia de los progenitores en todo caso.', 'atendido el interés de los solicitantes.'],
 t: 'En caso de oposición, el Juez, a petición del menor, hermanos, abuelos, parientes o allegados, resolverá atendidas las circunstancias', p: 'El Juez resuelve atendidas las circunstancias.'},
{k, a: 'art. 161', r: 'Visitas de menores desamparados', e: 'La Entidad Pública a la que esté encomendada la protección de menores regulará las visitas y comunicaciones respecto a los menores en situación de desamparo, pudiendo acordar motivadamente, en interés del menor, la suspensión temporal de las mismas con inmediata notificación:',
 o: ['al Ministerio Fiscal.', 'al Juez.', 'a los progenitores.', 'al Defensor del Pueblo.'],
 t: 'pudiendo acordar motivadamente, en interés del menor, la suspensión temporal de las mismas previa audiencia de los afectados y del menor si tuviere suficiente madurez y, en todo caso, si fuera mayor de doce años, con inmediata notificación al Ministerio Fiscal', p: 'Se notifica inmediatamente al Ministerio Fiscal.'},
{k, a: 'art. 161', r: 'Visitas de menores desamparados', e: 'El menor, los afectados y el Ministerio Fiscal podrán oponerse a las resoluciones administrativas sobre visitas y comunicaciones de menores desamparados:',
 o: ['conforme a la Ley de Enjuiciamiento Civil.', 'ante la propia Entidad Pública.', 'ante el Juzgado de lo Contencioso-Administrativo.', 'en el plazo de dos meses ante el Juzgado de Menores.'],
 t: 'El menor, los afectados y el Ministerio Fiscal podrán oponerse a dichas resoluciones administrativas conforme a la Ley de Enjuiciamiento Civil', p: 'Conforme a la Ley de Enjuiciamiento Civil.'},
{k, a: 'art. 162', r: 'Representación legal de los hijos', e: 'Los padres que ostenten la patria potestad tienen la representación legal de sus hijos menores no emancipados. Se exceptúan los actos relativos a los derechos de la personalidad que el hijo, de acuerdo con su madurez, pueda:',
 o: ['ejercitar por sí mismo.', 'ejercitar con asistencia de sus padres.', 'ejercitar con autorización judicial.', 'ejercitar una vez cumplidos los dieciséis años.'],
 t: 'Se exceptúan: 1.º Los actos relativos a los derechos de la personalidad que el hijo, de acuerdo con su madurez, pueda ejercitar por sí mismo', p: 'Los derechos de la personalidad que el hijo pueda ejercitar por sí mismo.'},
{k, a: 'art. 162', r: 'Representación legal de los hijos', e: 'Entre los actos exceptuados de la representación legal de los padres figuran aquellos:',
 o: ['en que exista conflicto de intereses entre los padres y el hijo.', 'que excedan de la administración ordinaria.', 'relativos a bienes inmuebles del hijo.', 'celebrados por el hijo mayor de dieciséis años.'],
 t: '2.º Aquellos en que exista conflicto de intereses entre los padres y el hijo', p: 'Cuando exista conflicto de intereses.'},
{k, a: 'art. 162', r: 'Representación legal de los hijos', e: 'Para celebrar contratos que obliguen al hijo a realizar prestaciones personales se requiere:',
 o: ['el previo consentimiento de éste si tuviere suficiente juicio.', 'el consentimiento de éste si es mayor de doce años.', 'la autorización judicial previa.', 'el consentimiento de ambos progenitores.'],
 t: 'Para celebrar contratos que obliguen al hijo a realizar prestaciones personales se requiere el previo consentimiento de éste si tuviere suficiente juicio', p: 'Previo consentimiento del hijo si tiene suficiente juicio.'},
{k, a: 'art. 163', r: 'Conflicto de intereses', e: 'Siempre que en algún asunto los progenitores tengan un interés opuesto al de sus hijos no emancipados, se nombrará a éstos:',
 o: ['un defensor que los represente en juicio y fuera de él.', 'un tutor ordinario que los represente en juicio.', 'un defensor que los represente solo en juicio.', 'un administrador judicial de sus bienes.'],
 t: 'Siempre que en algún asunto los progenitores tengan un interés opuesto al de sus hijos no emancipados, se nombrará a éstos un defensor que los represente en juicio y fuera de él', p: 'Se nombra un defensor que los represente en juicio y fuera de él.'},
{k, a: 'art. 163', r: 'Conflicto de intereses', e: 'Si el conflicto de intereses existiera solo con uno de los progenitores, corresponde al otro:',
 o: ['por Ley y sin necesidad de especial nombramiento representar al menor o completar su capacidad.', 'previo nombramiento judicial representar al menor o completar su capacidad.', 'por Ley y con autorización judicial representar al menor.', 'previa audiencia del Ministerio Fiscal, representar al menor.'],
 t: 'Si el conflicto de intereses existiera solo con uno de los progenitores, corresponde al otro por Ley y sin necesidad de especial nombramiento representar al menor o completar su capacidad', p: 'Lo representa el otro por ley, sin nombramiento especial.'},
{k, a: 'art. 164', r: 'Administración de los bienes de los hijos', e: 'Los padres administrarán los bienes de los hijos con la misma diligencia que los suyos propios, cumpliendo las obligaciones generales de todo administrador y las especiales establecidas en:',
 o: ['la Ley Hipotecaria.', 'la Ley de Enjuiciamiento Civil.', 'la Ley del Notariado.', 'la Ley del Registro Civil.'],
 t: 'cumpliendo las obligaciones generales de todo administrador y las especiales establecidas en la Ley Hipotecaria', p: 'Las especiales de la Ley Hipotecaria.'},
{k, a: 'art. 164', r: 'Administración de los bienes de los hijos', e: 'Se exceptúan de la administración paterna los bienes que el hijo mayor de dieciséis años hubiera adquirido con su trabajo o industria. Los actos de administración ordinaria serán realizados por el hijo, que necesitará:',
 o: ['el consentimiento de los padres para los que excedan de ella.', 'la autorización judicial para los que excedan de ella.', 'la asistencia del Ministerio Fiscal en todo caso.', 'el consentimiento de ambos progenitores y del Juez.'],
 t: 'Los que el hijo mayor de dieciséis años hubiera adquirido con su trabajo o industria. Los actos de administración ordinaria serán realizados por el hijo, que necesitará el consentimiento de los padres para los que excedan de ella', p: 'Necesita el consentimiento de los padres para lo que exceda de la administración ordinaria.'},
{k, a: 'art. 164', r: 'Administración de los bienes de los hijos', e: 'Se exceptúan de la administración paterna los bienes adquiridos por título gratuito cuando el disponente lo hubiere ordenado de manera expresa. Se cumplirá estrictamente:',
 o: ['la voluntad de éste sobre la administración de estos bienes y destino de sus frutos.', 'la voluntad del hijo sobre la administración de estos bienes.', 'la decisión del Juez sobre el destino de los frutos.', 'la voluntad de los padres sobre el destino de los frutos.'],
 t: 'Se cumplirá estrictamente la voluntad de éste sobre la administración de estos bienes y destino de sus frutos', p: 'Se cumple estrictamente la voluntad del disponente.'},
{k, a: 'art. 165', r: 'Frutos de los bienes de los hijos', e: 'Pertenecen siempre al hijo no emancipado los frutos de sus bienes, así como todo lo que adquiera con su trabajo o industria. No obstante, los padres podrán destinar los del menor que viva con ambos o con uno sólo de ellos, en la parte que le corresponda, al levantamiento de las cargas familiares, y no estarán obligados a:',
 o: ['rendir cuentas de lo que hubiesen consumido en tales atenciones.', 'solicitar autorización judicial para su uso.', 'reponer lo consumido al alcanzar el hijo la mayoría de edad.', 'comunicar el destino de los frutos al Ministerio Fiscal.'],
 t: 'los padres podrán destinar los del menor que viva con ambos o con uno sólo de ellos, en la parte que le corresponda, al levantamiento de las cargas familiares, y no estarán obligados a rendir cuentas de lo que hubiesen consumido en tales atenciones', p: 'No están obligados a rendir cuentas.'},
{k, a: 'art. 166', r: 'Disposición de los bienes de los hijos', e: 'Los padres no podrán renunciar a los derechos de que los hijos sean titulares ni enajenar o gravar sus bienes inmuebles, establecimientos mercantiles o industriales, objetos preciosos y valores mobiliarios, sino por causas justificadas de utilidad o necesidad y previa la autorización del Juez del domicilio, con audiencia:',
 o: ['del Ministerio Fiscal.', 'del hijo mayor de doce años.', 'de ambos progenitores.', 'del Equipo Técnico Judicial.'],
 t: 'sino por causas justificadas de utilidad o necesidad y previa la autorización del Juez del domicilio, con audiencia del Ministerio Fiscal', p: 'Con audiencia del Ministerio Fiscal.'},
{k, a: 'art. 166', r: 'Disposición de los bienes de los hijos', e: 'Los padres deberán recabar autorización judicial para repudiar la herencia o legado deferidos al hijo. Si el Juez denegase la autorización:',
 o: ['la herencia sólo podrá ser aceptada a beneficio de inventario.', 'la herencia deberá ser aceptada pura y simplemente.', 'la herencia pasará al siguiente llamado a la sucesión.', 'el hijo deberá aceptar la herencia al alcanzar la mayoría de edad.'],
 t: 'Si el Juez denegase la autorización, la herencia sólo podrá ser aceptada a beneficio de inventario', p: 'Solo podrá aceptarse a beneficio de inventario.'},
{k, a: 'art. 166', r: 'Disposición de los bienes de los hijos', e: 'No será necesaria autorización judicial para disponer de bienes del hijo si el menor hubiese cumplido dieciséis años y consintiere:',
 o: ['en documento público.', 'ante el Ministerio Fiscal.', 'en presencia de ambos progenitores.', 'ante el Juez del domicilio.'],
 t: 'No será necesaria autorización judicial si el menor hubiese cumplido dieciséis años y consintiere en documento público', p: 'Con dieciséis años y consentimiento en documento público.'},
{k, a: 'art. 166', r: 'Disposición de los bienes de los hijos', e: 'No será necesaria autorización judicial para la enajenación de valores mobiliarios del hijo siempre que:',
 o: ['su importe se reinvierta en bienes o valores seguros.', 'el hijo sea mayor de doce años.', 'el valor no exceda del límite fijado por el Juez.', 'se cuente con informe del Ministerio Fiscal.'],
 t: 'ni para la enajenación de valores mobiliarios siempre que su importe se reinvierta en bienes o valores seguros', p: 'Siempre que el importe se reinvierta en bienes o valores seguros.'},
{k, a: 'art. 167', r: 'Peligro para el patrimonio del hijo', e: 'Cuando la administración de los progenitores ponga en peligro el patrimonio del hijo, el Juez, a petición del propio hijo, del Ministerio Fiscal o de cualquier pariente del menor, podrá adoptar las medidas que estime necesarias para la seguridad y recaudo de los bienes, exigir caución o fianza para la continuación en la administración o incluso:',
 o: ['nombrar un Administrador.', 'privar a los padres de la patria potestad.', 'nombrar un tutor.', 'sustituir a los progenitores por el Ministerio Fiscal.'],
 t: 'podrá adoptar las medidas que estime necesarias para la seguridad y recaudo de los bienes, exigir caución o fianza para la continuación en la administración o incluso nombrar un Administrador', p: 'Incluso nombrar un Administrador.'},
{k, a: 'art. 168', r: 'Rendición de cuentas', e: 'Al término de la patria potestad podrán los hijos exigir a los padres la rendición de cuentas de la administración que ejercieron sobre sus bienes hasta entonces. La acción para exigir el cumplimiento de esta obligación prescribirá:',
 o: ['a los tres años.', 'a los cinco años.', 'a los dos años.', 'al año.'],
 t: 'La acción para exigir el cumplimiento de esta obligación prescribirá a los tres años', p: 'Prescribe a los tres años.'},
{k, a: 'art. 168', r: 'Rendición de cuentas', e: 'En caso de pérdida o deterioro de los bienes del hijo por dolo o culpa grave:',
 o: ['responderán los padres de los daños y perjuicios sufridos.', 'responderá subsidiariamente el Estado.', 'responderá el Ministerio Fiscal de forma solidaria.', 'responderán los padres solo por la pérdida, no por el deterioro.'],
 t: 'En caso de pérdida o deterioro de los bienes por dolo o culpa grave, responderán los padres de los daños y perjuicios sufridos', p: 'Responden los padres de los daños y perjuicios.'},
{k, a: 'art. 169', r: 'Extinción de la patria potestad', e: 'La patria potestad se acaba:',
 o: ['por la muerte o la declaración de fallecimiento de los padres o del hijo, por la emancipación y por la adopción del hijo.', 'por la muerte de los padres o del hijo, por la emancipación y por contraer matrimonio.', 'por la muerte o la declaración de fallecimiento de los padres o del hijo y por la mayoría de edad.', 'por la muerte de los padres, por la emancipación y por la privación judicial.'],
 t: 'La patria potestad se acaba: 1.° Por la muerte o la declaración de fallecimiento de los padres o del hijo. 2.° Por la emancipación. 3.° Por la adopción del hijo', p: 'Muerte o fallecimiento, emancipación y adopción.'},
{k, a: 'art. 170', r: 'Privación de la patria potestad', e: 'Cualquiera de los progenitores podrá ser privado total o parcialmente de su potestad por sentencia fundada en el incumplimiento de los deberes inherentes a la misma o dictada en:',
 o: ['causa criminal o matrimonial.', 'causa criminal o administrativa.', 'procedimiento de jurisdicción voluntaria.', 'causa matrimonial o de desamparo.'],
 t: 'Cualquiera de los progenitores podrá ser privado total o parcialmente de su potestad por sentencia fundada en el incumplimiento de los deberes inherentes a la misma o dictada en causa criminal o matrimonial', p: 'Causa criminal o matrimonial.'},
{k, a: 'art. 170', r: 'Privación de la patria potestad', e: 'Los Tribunales podrán, en beneficio e interés del hijo, acordar la recuperación de la patria potestad:',
 o: ['cuando hubiere cesado la causa que motivó la privación.', 'transcurridos dos años desde la privación.', 'cuando lo solicite el Ministerio Fiscal.', 'cuando el hijo alcance los dieciséis años.'],
 t: 'Los Tribunales podrán, en beneficio e interés del hijo, acordar la recuperación de la patria potestad cuando hubiere cesado la causa que motivó la privación', p: 'Cuando haya cesado la causa de la privación.'},
{k, a: 'art. 172.1', r: 'Desamparo', e: 'Cuando la Entidad Pública constate que un menor se encuentra en situación de desamparo, tiene por ministerio de la ley la tutela del mismo y deberá adoptar las medidas de protección necesarias para su guarda, poniéndolo en conocimiento:',
 o: ['del Ministerio Fiscal y, en su caso, del Juez que acordó la tutela ordinaria.', 'del Juez y de los progenitores.', 'del Ministerio Fiscal y del Defensor del Pueblo.', 'del Juez de Menores, exclusivamente.'],
 t: 'tiene por ministerio de la ley la tutela del mismo y deberá adoptar las medidas de protección necesarias para su guarda, poniéndolo en conocimiento del Ministerio Fiscal y, en su caso, del Juez que acordó la tutela ordinaria', p: 'Se comunica al Ministerio Fiscal y, en su caso, al Juez de la tutela ordinaria.'},
{k, a: 'art. 172.1', r: 'Desamparo', e: 'La resolución administrativa que declare la situación de desamparo y las medidas adoptadas se notificará en legal forma a los progenitores, tutores o guardadores y al menor afectado si tuviere suficiente madurez y, en todo caso, si fuere mayor de doce años, de forma inmediata sin que sobrepase el plazo máximo de:',
 o: ['cuarenta y ocho horas.', 'setenta y dos horas.', 'veinticuatro horas.', 'diez días.'],
 t: 'de forma inmediata sin que sobrepase el plazo máximo de cuarenta y ocho horas', p: 'El plazo máximo es de cuarenta y ocho horas.'},
{k, a: 'art. 172.1', r: 'Desamparo', e: 'Se considera como situación de desamparo la que se produce de hecho a causa del incumplimiento o del imposible o inadecuado ejercicio de los deberes de protección establecidos por las leyes para la guarda de los menores, cuando éstos queden privados de:',
 o: ['la necesaria asistencia moral o material.', 'la necesaria asistencia médica o educativa.', 'la convivencia con sus progenitores.', 'la protección de la autoridad judicial.'],
 t: 'cuando éstos queden privados de la necesaria asistencia moral o material', p: 'Privados de la necesaria asistencia moral o material.'},
{k, a: 'art. 172.1', r: 'Desamparo', e: 'La asunción de la tutela atribuida a la Entidad Pública lleva consigo la suspensión de la patria potestad o de la tutela ordinaria. No obstante:',
 o: ['serán válidos los actos de contenido patrimonial que realicen los progenitores o tutores en representación del menor y que sean en interés de éste.', 'serán válidos los actos de contenido personal que realicen los progenitores.', 'serán válidos todos los actos que realicen los progenitores o tutores.', 'serán válidos los actos patrimoniales aprobados por el Juez.'],
 t: 'No obstante, serán válidos los actos de contenido patrimonial que realicen los progenitores o tutores en representación del menor y que sean en interés de éste', p: 'Valen los actos patrimoniales realizados en interés del menor.'},
{k, a: 'art. 172.2', r: 'Desamparo: plazo de oposición', e: 'Durante el plazo de dos años desde la notificación de la resolución administrativa por la que se declare la situación de desamparo, los progenitores que continúen ostentando la patria potestad pero la tengan suspendida podrán solicitar a la Entidad Pública:',
 o: ['que cese la suspensión y quede revocada la declaración de situación de desamparo del menor.', 'que se declare la nulidad de la declaración de desamparo.', 'que se constituya una tutela ordinaria.', 'que se suspenda cautelarmente la adopción del menor.'],
 t: 'podrán solicitar a la Entidad Pública que cese la suspensión y quede revocada la declaración de situación de desamparo del menor', p: 'Pueden pedir el cese de la suspensión y la revocación del desamparo.'},
{k, a: 'art. 172.2', r: 'Desamparo: plazo de oposición', e: 'Transcurridos los dos años desde la notificación de la declaración de desamparo, quién estará legitimado para oponerse a la resolución de la Entidad Pública:',
 o: ['únicamente el Ministerio Fiscal.', 'los progenitores y el Ministerio Fiscal.', 'únicamente los progenitores.', 'el menor y el Ministerio Fiscal.'],
 t: 'En todo caso, transcurridos los dos años, únicamente el Ministerio Fiscal estará legitimado para oponerse a la resolución de la Entidad Pública', p: 'Únicamente el Ministerio Fiscal.'},
{k, a: 'art. 172.2', r: 'Desamparo: plazo de oposición', e: 'Durante el plazo de dos años, la Entidad Pública, ponderando la situación y poniéndola en conocimiento del Ministerio Fiscal, podrá adoptar cualquier medida de protección, incluida la propuesta de adopción, cuando exista:',
 o: ['un pronóstico fundado de imposibilidad definitiva de retorno a la familia de origen.', 'una petición expresa de los acogedores.', 'una solicitud de los progenitores.', 'un informe favorable del Equipo Técnico Judicial.'],
 t: 'podrá adoptar cualquier medida de protección, incluida la propuesta de adopción, cuando exista un pronóstico fundado de imposibilidad definitiva de retorno a la familia de origen', p: 'Cuando exista pronóstico fundado de imposibilidad definitiva de retorno.'},
{k, a: 'art. 172.3', r: 'Desamparo: revocación', e: 'La Entidad Pública, de oficio o a instancia del Ministerio Fiscal o de persona o entidad interesada, podrá revocar la declaración de situación de desamparo y decidir el retorno del menor con su familia, siempre que se entienda que es lo más adecuado para su interés. Dicha decisión se notificará:',
 o: ['al Ministerio Fiscal.', 'al Juez.', 'a los progenitores únicamente.', 'al menor y a sus acogedores.'],
 t: 'Dicha decisión se notificará al Ministerio Fiscal', p: 'Se notifica al Ministerio Fiscal.'},
{k, a: 'art. 172.4', r: 'Guarda provisional', e: 'En cumplimiento de la obligación de prestar la atención inmediata, la Entidad Pública podrá asumir la guarda provisional de un menor mediante resolución administrativa, y lo comunicará:',
 o: ['al Ministerio Fiscal.', 'al Juez de Menores.', 'a los progenitores.', 'al Defensor del Pueblo.'],
 t: 'la Entidad Pública podrá asumir la guarda provisional de un menor mediante resolución administrativa, y lo comunicará al Ministerio Fiscal', p: 'Se comunica al Ministerio Fiscal.'},
{k, a: 'art. 172.5', r: 'Cese de la tutela administrativa', e: 'La Entidad Pública cesará en la tutela que ostente sobre los menores declarados en situación de desamparo cuando compruebe fehacientemente alguna de las siguientes circunstancias. Señale la INCORRECTA:',
 o: ['Que hayan transcurrido seis meses desde que el menor abandonó voluntariamente el centro de protección, encontrándose en paradero desconocido.', 'Que el menor se ha trasladado voluntariamente a otro país.', 'Que el menor se encuentra en el territorio de otra comunidad autónoma, en cuyo caso se procederá al traslado del expediente de protección.', 'Que hayan desaparecido las causas que motivaron la asunción de la tutela.'],
 t: 'c) Que hayan transcurrido doce meses desde que el menor abandonó voluntariamente el centro de protección, encontrándose en paradero desconocido', p: 'El plazo es de doce meses, no seis.'},
{k, a: 'art. 172 bis.1', r: 'Guarda voluntaria', e: 'Cuando los progenitores o tutores, por circunstancias graves y transitorias debidamente acreditadas, no puedan cuidar al menor, podrán solicitar de la Entidad Pública que ésta asuma su guarda durante el tiempo necesario, que no podrá sobrepasar:',
 o: ['dos años como plazo máximo de cuidado temporal del menor, salvo que el interés superior del menor aconseje, excepcionalmente, la prórroga de las medidas.', 'un año como plazo máximo de cuidado temporal, sin posibilidad de prórroga.', 'tres años como plazo máximo, prorrogable por otro año.', 'dos años como plazo máximo, sin posibilidad de prórroga.'],
 t: 'que no podrá sobrepasar dos años como plazo máximo de cuidado temporal del menor, salvo que el interés superior del menor aconseje, excepcionalmente, la prórroga de las medidas', p: 'Máximo dos años, con prórroga excepcional.'},
{k, a: 'art. 172 bis.1', r: 'Guarda voluntaria', e: 'La entrega voluntaria de la guarda de un menor a la Entidad Pública se hará:',
 o: ['por escrito, dejando constancia de que los progenitores o tutores han sido informados de las responsabilidades que siguen manteniendo respecto del menor.', 'ante el Juez, con audiencia del Ministerio Fiscal.', 'de forma verbal o escrita, a elección de los progenitores.', 'por escrito, con aprobación judicial previa.'],
 t: 'La entrega voluntaria de la guarda se hará por escrito dejando constancia de que los progenitores o tutores han sido informados de las responsabilidades que siguen manteniendo respecto del menor', p: 'Se hace por escrito y con constancia de la información.'},
{k, a: 'art. 172 ter.1', r: 'Guarda: acogimiento', e: 'La guarda se realizará mediante el acogimiento familiar y, no siendo éste posible o conveniente para el interés del menor, mediante:',
 o: ['el acogimiento residencial.', 'el acogimiento preadoptivo.', 'la tutela ordinaria.', 'la guarda de hecho.'],
 t: 'La guarda se realizará mediante el acogimiento familiar y, no siendo éste posible o conveniente para el interés del menor, mediante el acogimiento residencial', p: 'El acogimiento residencial es subsidiario del familiar.'},
{k, a: 'art. 172 ter.1', r: 'Guarda: acogimiento', e: 'El acogimiento residencial se ejercerá por:',
 o: ['el Director o responsable del centro donde esté acogido el menor, conforme a los términos establecidos en la legislación de protección de menores.', 'la Entidad Pública a través de su representante legal.', 'el Juez de Menores del lugar del centro.', 'el responsable de la Entidad Pública que haya declarado el desamparo.'],
 t: 'El acogimiento residencial se ejercerá por el Director o responsable del centro donde esté acogido el menor, conforme a los términos establecidos en la legislación de protección de menores', p: 'Lo ejerce el Director o responsable del centro.'},
{k, a: 'art. 172 ter.2', r: 'Guarda: revisión', e: 'La situación del menor en relación con su familia de origen, tanto en lo que se refiere a su guarda como al régimen de visitas y otras formas de comunicación, será revisada:',
 o: ['al menos cada seis meses.', 'al menos cada año.', 'al menos cada tres meses.', 'al menos cada dos años.'],
 t: 'La situación del menor en relación con su familia de origen, tanto en lo que se refiere a su guarda como al régimen de visitas y otras formas de comunicación, será revisada, al menos cada seis meses', p: 'Se revisa al menos cada seis meses.'},
{k, a: 'art. 172 ter.3', r: 'Guarda: estancias', e: 'La Entidad Pública podrá acordar, en relación con el menor en acogida familiar o residencial, estancias, salidas de fines de semana o de vacaciones con familias o con instituciones dedicadas a estas funciones. Dichas medidas deberán ser acordadas una vez haya sido oído el menor si tuviere suficiente madurez y, en todo caso, si fuera mayor de:',
 o: ['doce años.', 'catorce años.', 'dieciséis años.', 'diez años.'],
 t: 'Dichas medidas deberán ser acordadas una vez haya sido oído el menor si tuviere suficiente madurez y, en todo caso, si fuera mayor de doce años', p: 'Se oye en todo caso al mayor de doce años.'},
{k, a: 'art. 172 ter.4', r: 'Guarda: contribución económica', e: 'En los casos de declaración de situación de desamparo o de asunción de la guarda, podrá establecerse por la Entidad Pública la cantidad que deben abonar los progenitores o tutores para contribuir, en concepto de alimentos y en función de sus posibilidades, a los gastos derivados:',
 o: ['del cuidado y atención del menor, así como los derivados de la responsabilidad civil que pudiera imputarse a los menores por actos realizados por los mismos.', 'del cuidado y atención del menor, excluida la responsabilidad civil por sus actos.', 'de la educación del menor y de la responsabilidad civil de los progenitores.', 'de la asistencia sanitaria del menor y de su residencia.'],
 t: 'a los gastos derivados del cuidado y atención del menor, así como los derivados de la responsabilidad civil que pudiera imputarse a los menores por actos realizados por los mismos', p: 'Incluye gastos de cuidado y de responsabilidad civil del menor.'},
{k, a: 'art. 173.1', r: 'Acogimiento familiar', e: 'El acogimiento familiar produce la plena participación del menor en la vida de familia e impone a quien lo recibe las obligaciones de:',
 o: ['velar por él, tenerlo en su compañía, alimentarlo, educarlo y procurarle una formación integral en un entorno afectivo.', 'representarlo legalmente y administrar su patrimonio.', 'velar por él y asumir la patria potestad.', 'alimentarlo y educarlo, sin obligación de tenerlo en su compañía.'],
 t: 'impone a quien lo recibe las obligaciones de velar por él, tenerlo en su compañía, alimentarlo, educarlo y procurarle una formación integral en un entorno afectivo', p: 'Velar, tenerlo en compañía, alimentar, educar y formar.'},
{k, a: 'art. 173.2', r: 'Acogimiento familiar', e: 'El acogimiento requerirá el consentimiento de los acogedores y del menor acogido si tuviera suficiente madurez y, en todo caso, si fuera mayor de:',
 o: ['doce años.', 'catorce años.', 'dieciséis años.', 'diez años.'],
 t: 'El acogimiento requerirá el consentimiento de los acogedores y del menor acogido si tuviera suficiente madurez y, en todo caso, si fuera mayor de doce años', p: 'En todo caso, mayor de doce años.'},
{k, a: 'art. 173.3', r: 'Acogimiento familiar', e: 'Si surgieren problemas graves de convivencia entre el menor y la persona o personas a quien hubiere sido confiado la guarda en acogimiento familiar, podrán solicitar a la Entidad Pública la remoción de la guarda:',
 o: ['el menor, el acogedor, el Ministerio Fiscal, los progenitores o tutor que no estuvieran privados de la patria potestad o de la tutela o cualquier persona interesada.', 'solo el menor y el acogedor.', 'el Ministerio Fiscal y el Juez de oficio.', 'los progenitores, aunque estuvieran privados de la patria potestad.'],
 t: 'aquél, el acogedor, el Ministerio Fiscal, los progenitores o tutor que no estuvieran privados de la patria potestad o de la tutela o cualquier persona interesada podrán solicitar a la Entidad Pública la remoción de la guarda', p: 'Pueden solicitarlo el menor, el acogedor, el Fiscal, progenitores o tutor no privados y cualquier interesado.'},
{k, a: 'art. 173.4', r: 'Acogimiento familiar: cese', e: 'El acogimiento familiar del menor cesará. Señale la INCORRECTA:',
 o: ['Por el cumplimiento de los dieciséis años del menor.', 'Por resolución judicial.', 'Por la muerte o declaración de fallecimiento del acogedor o acogedores del menor.', 'Por la mayoría de edad del menor.'],
 t: 'Por la muerte o declaración de fallecimiento del acogedor o acogedores del menor', p: 'Cesa por la mayoría de edad, no por cumplir dieciséis años.'},
{k, a: 'art. 173.5', r: 'Acogimiento familiar', e: 'Todas las actuaciones de formalización y cesación del acogimiento se practicarán:',
 o: ['con la obligada reserva.', 'con publicidad en el Registro Civil.', 'ante el Juez competente.', 'con audiencia del Ministerio Fiscal.'],
 t: 'Todas las actuaciones de formalización y cesación del acogimiento se practicarán con la obligada reserva', p: 'Con la obligada reserva.'},
{k, a: 'art. 173 bis.1', r: 'Modalidades de acogimiento', e: 'El acogimiento familiar podrá tener lugar en la propia familia extensa del menor o en familia ajena, pudiendo en este último caso ser:',
 o: ['especializado.', 'permanente exclusivamente.', 'de urgencia exclusivamente.', 'profesional.'],
 t: 'El acogimiento familiar podrá tener lugar en la propia familia extensa del menor o en familia ajena, pudiendo en este último caso ser especializado', p: 'En familia ajena puede ser especializado.'},
{k, a: 'art. 173 bis.2', r: 'Modalidades de acogimiento', e: 'El acogimiento familiar de urgencia, principalmente para menores de seis años, tendrá una duración no superior a:',
 o: ['seis meses, en tanto se decide la medida de protección familiar que corresponda.', 'tres meses, en tanto se decide la medida de protección familiar.', 'un año, en tanto se constituye el acogimiento permanente.', 'dos años, en tanto se decide la adopción.'],
 t: 'Acogimiento familiar de urgencia, principalmente para menores de seis años, que tendrá una duración no superior a seis meses, en tanto se decide la medida de protección familiar que corresponda', p: 'No superior a seis meses.'},
{k, a: 'art. 173 bis.2', r: 'Modalidades de acogimiento', e: 'El acogimiento familiar temporal tendrá una duración máxima de dos años, salvo que:',
 o: ['el interés superior del menor aconseje la prórroga de la medida por la previsible e inmediata reintegración familiar, o la adopción de otra medida de protección definitiva.', 'lo solicite la familia acogedora.', 'lo disponga el Ministerio Fiscal.', 'el menor cumpla los doce años durante ese plazo.'],
 t: 'Este acogimiento tendrá una duración máxima de dos años, salvo que el interés superior del menor aconseje la prórroga de la medida por la previsible e inmediata reintegración familiar, o la adopción de otra medida de protección definitiva', p: 'Se prorroga si lo aconseja el interés superior del menor.'},
{k, a: 'art. 173 bis.2', r: 'Modalidades de acogimiento', e: 'El acogimiento familiar permanente se constituirá bien al finalizar el plazo de dos años de acogimiento temporal por no ser posible la reintegración familiar, o bien directamente:',
 o: ['en casos de menores con necesidades especiales o cuando las circunstancias del menor y su familia así lo aconsejen.', 'en casos de menores de seis años.', 'en casos de menores con medidas judiciales de protección.', 'en casos de menores sin familia extensa.'],
 t: 'o bien directamente en casos de menores con necesidades especiales o cuando las circunstancias del menor y su familia así lo aconsejen', p: 'Directamente en casos de menores con necesidades especiales.'},
{k, a: 'art. 173 bis.2', r: 'Modalidades de acogimiento', e: 'En el acogimiento familiar permanente la Entidad Pública podrá solicitar del Juez que atribuya a los acogedores permanentes:',
 o: ['aquellas facultades de la tutela que faciliten el desempeño de sus responsabilidades, atendiendo, en todo caso, al interés superior del menor.', 'la patria potestad del menor.', 'la representación legal del menor en todo caso.', 'la facultad de adoptar al menor.'],
 t: 'La Entidad Pública podrá solicitar del Juez que atribuya a los acogedores permanentes aquellas facultades de la tutela que faciliten el desempeño de sus responsabilidades, atendiendo, en todo caso, al interés superior del menor', p: 'Facultades de la tutela que faciliten sus responsabilidades.'},
{k, a: 'art. 174', r: 'Vigilancia del Ministerio Fiscal', e: 'Incumbe al Ministerio Fiscal la superior vigilancia de la tutela, acogimiento o guarda de los menores. A tal fin, la Entidad Pública le dará noticia inmediata de los nuevos ingresos de menores y le remitirá copia de las resoluciones administrativas de formalización de:',
 o: ['la constitución, variación y cesación de las tutelas, guardas y acogimientos.', 'la constitución y cesación de las tutelas, pero no de las guardas.', 'la constitución de las tutelas y acogimientos, exclusivamente.', 'la variación de las guardas y acogimientos, exclusivamente.'],
 t: 'le remitirá copia de las resoluciones administrativas de formalización de la constitución, variación y cesación de las tutelas, guardas y acogimientos', p: 'Constitución, variación y cesación de tutelas, guardas y acogimientos.'},
{k, a: 'art. 174', r: 'Vigilancia del Ministerio Fiscal', e: 'El Ministerio Fiscal habrá de comprobar la situación del menor y promoverá ante la Entidad Pública o el Juez, según proceda, las medidas de protección que estime necesarias:',
 o: ['al menos semestralmente.', 'al menos anualmente.', 'al menos trimestralmente.', 'al menos cada dos años.'],
 t: 'El Ministerio Fiscal habrá de comprobar, al menos semestralmente, la situación del menor y promoverá ante la Entidad Pública o el Juez, según proceda, las medidas de protección que estime necesarias', p: 'Al menos semestralmente.'},
{k, a: 'art. 174', r: 'Vigilancia del Ministerio Fiscal', e: 'La vigilancia del Ministerio Fiscal no eximirá a la Entidad Pública de:',
 o: ['su responsabilidad para con el menor y de su obligación de poner en conocimiento del Ministerio Fiscal las anomalías que observe.', 'su obligación de comunicar al Juez las variaciones de la guarda.', 'su deber de informar a los progenitores cada seis meses.', 'su responsabilidad económica por los daños del menor.'],
 t: 'La vigilancia del Ministerio Fiscal no eximirá a la Entidad Pública de su responsabilidad para con el menor y de su obligación de poner en conocimiento del Ministerio Fiscal las anomalías que observe', p: 'Mantiene su responsabilidad y su deber de comunicar anomalías.'},
];
require('./preguntas-t10r-lib.js').run({ bloque: 5, Q });
